// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 blockNumber, uint256 blockTimestamp, uint256 msgValue) public {
        // Constrain inputs to satisfy the require conditions in fallback
        vm.assume(msgValue == 10 ether);
        vm.assume(blockTimestamp > c.pastBlockTime());

        // Set the block environment for the call
        vm.roll(blockNumber);
        vm.warp(blockTimestamp);

        // Send value to trigger fallback
        (bool success,) = address(c).call{value: msgValue}("");

        // Assert the rule: if call succeeded, pastBlockTime equals the block timestamp
        assertTrue(!success || c.pastBlockTime() == blockTimestamp);
    }
}

